/**
  @file
  @brief A program to try in the demo

  Press Run in Studio. This host has no SAS binary, so the site answers with a
  recorded session of this program - the log, the two-page listing and the webout
  are that session's output, with the "Licensed to ..., Site ..." line removed.
  Any other .sas program is refused: the recording names this one, and a demo
  that invented a session for every program would be teaching the wrong thing.
**/

libname demo "/sasjs/drive/files/Public/demo";
options fmterr nodsnferr;

data demo.orders;
set demo.orders_raw;
where order_date >= '01JAN2026'd;
amount_gbp = amount * fx_rate;
if missing(fx_rate) then amount_gbp = 0;
run;
data demo.orders2;
infile datalines dsd truncover;
input order_id $ order_date :date9. amount :comma.;
datalines;
A-10418,15JAN2026,"1,284.50"
A-10419,15JAN2026,902.10
A-10420,32JAN2026,741.25
A-10421,16JAN2026,"2,210.00"
A-10422,17JAN2026,N/A
;
proc print data=demo.orders(obs=5);
var order_id order_date customer amount_gbp;
run;
proc sort data=demo.orders out=demo.orders_sorted;
by customer amount_gbp;
run;
proc sql;
create table demo.totals as
select customer, sum(amount_gbp) as total_gbp
from demo.orders
group by customer;
data demo.merged;
merge demo.orders(in=a) demo.orders2(in=b);
by order_id;
if a and b then matched = 1;
else matched = 0;
run;
data demo.flagged;
set demo.totals;
if total_gbp > 10000 then flag = 'HIGH';
else if total_gbp > &threshold then flag = 'MEDIUM';
else flag = 'LOW';
run;
data demo.bad;
set demo.orders;
net = amount_gbp - refund_amt;
run;
proc means data=demo.orders mean min max;
var amount_gbp;
proc print data=demo.totals(obs=3);
run;

files./sasjs/drive/files/home/sasjsadmin/run.j:
/**
  @file
  @brief A program that DOES run in this browser

  Press Run in Studio: the service worker executes this file, the same way
  sasjs/server would execute it, and the log and webout appear in their tabs.
**/

const rows = [
  { name: 'Alice', age: 14 },
  { name: 'Bob', age: 15 },
  { name: 'Carol', age: 13 }
]

console.log(`Read ${rows.length} rows`)

// The three calls a JS stored program makes on sasjs/server, in the order it
// makes them: OPEN starts the body, OBJ writes a table keyed by column name,
// CLOSE adds the system block and closes the object. webout() is not a
// data sink - a bare array is refused, here and on the server, because the two
// hosts generate the same block.
webout('OPEN')
webout('OBJ', 'adults', rows.filter((row) => row.age > 13))
webout('CLOSE')
